create table public.activities (id uuid primary key default gen_random_uuid(), competency_id uuid not null references public.competencies(id) on delete restrict, type text not null, title text not null, instructions text, difficulty smallint not null check (difficulty >= 1), configuration jsonb not null default '{}'::jsonb, scoring_configuration jsonb, status text not null default 'draft', created_by uuid not null references public.profiles(id) on delete restrict, published_by uuid references public.profiles(id) on delete set null, published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());;
